import type { Pack, Track } from '../types';
import briceno from './briceno.json';
import animeLatino from './anime-latino.json';

// New packs are generated by scripts/import-txt.mjs and registered here.
// groupBy names the hint that splits a pack into filters ("solo Fother Muckers", "solo endings").
export const PACKS: Pack[] = [
  { ...briceno, groupBy: 'Proyecto' },
  { ...animeLatino, groupBy: 'Tipo' },
];

/** Tracks without a video are skipped so the catalog can be filled gradually. */
export function playableTracks(pack: Pack) {
  return pack.tracks.filter((t) => t.youtubeId.trim() !== '');
}

/** What to play: some packs, each optionally narrowed to some groups (empty = the whole pack). */
export type Selection = { id: string; groups: string[] }[];

export const DEFAULT_SELECTION: Selection = [{ id: PACKS[0].id, groups: [] }];

/** "Opening 2" and "Opening" are the same filter. */
export function trackGroup(pack: Pack, track: Track) {
  const value = track.hints.find((h) => h.label === pack.groupBy)?.value;
  return value ? value.replace(/\s*\d+$/, '') : null;
}

export function packGroups(pack: Pack) {
  const groups = new Set<string>();
  for (const t of playableTracks(pack)) {
    const g = trackGroup(pack, t);
    if (g) groups.add(g);
  }
  return [...groups].sort((a, b) => a.localeCompare(b, 'es'));
}

/** Drops unknown packs/groups so a selection coming from the network or an old save is always valid. */
export function cleanSelection(input: unknown): Selection {
  if (!Array.isArray(input)) return DEFAULT_SELECTION;
  const out: Selection = [];
  for (const item of input) {
    const pack = PACKS.find((p) => p.id === item?.id);
    if (!pack || out.some((s) => s.id === pack.id)) continue;
    const valid = packGroups(pack);
    const groups = Array.isArray(item.groups) ? item.groups.filter((g: unknown) => valid.includes(String(g))) : [];
    out.push({ id: pack.id, groups: groups.length === valid.length ? [] : groups });
  }
  return out.length ? out : DEFAULT_SELECTION;
}

function selectionName(selection: Selection) {
  return selection
    .map(({ id, groups }) => {
      const pack = PACKS.find((p) => p.id === id)!;
      return groups.length ? `${pack.name} (${groups.join(', ')})` : pack.name;
    })
    .join(' + ');
}

/** One playable pack out of a selection. Autocomplete keeps every name of the chosen packs so filters don't narrow it. */
export function buildPack(selection: Selection): Pack {
  const packs = selection.map((s) => ({ pack: PACKS.find((p) => p.id === s.id)!, groups: s.groups }));
  const tracks = packs.flatMap(({ pack, groups }) =>
    playableTracks(pack).filter((t) => groups.length === 0 || groups.includes(trackGroup(pack, t) ?? '')),
  );
  const answers = [...new Set(packs.flatMap(({ pack }) => pack.tracks.map((t) => t.answer)))].sort((a, b) =>
    a.localeCompare(b, 'es'),
  );
  const single = packs.length === 1 ? packs[0].pack : null;
  return {
    id: selection.map((s) => s.id).join('+'),
    name: selectionName(selection),
    description: '',
    answerLabel: single?.answerLabel ?? 'respuesta',
    guessPlaceholder: single?.guessPlaceholder ?? 'Escribe tu respuesta…',
    tracks,
    answers,
  };
}

/** Autocomplete options for a pack. */
export function answerOptions(pack: Pack) {
  return pack.answers ?? [...new Set(pack.tracks.map((t) => t.answer))].sort((a, b) => a.localeCompare(b, 'es'));
}
